selector_to_html = {"a[href=\"#pycmplot.liftover.liftover_hg19_to_hg38\"]": "<dt class=\"sig sig-object py\" id=\"pycmplot.liftover.liftover_hg19_to_hg38\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pycmplot.liftover.</span></span><span class=\"sig-name descname\"><span class=\"pre\">liftover_hg19_to_hg38</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chrom</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">str</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">pos</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">int</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">resources</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"resources.html#pycmplot.resources.ResourceConfig\" title=\"pycmplot.resources.ResourceConfig\"><span class=\"pre\">ResourceConfig</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><span class=\"pre\">int</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span></span><a class=\"reference internal\" href=\"../_modules/pycmplot/liftover.html#liftover_hg19_to_hg38\"><span class=\"viewcode-link\"><span class=\"pre\">[source]</span></span></a></dt><dd><p>Convert a single hg19 position to its hg38 equivalent.</p><p>Uses a lazily loaded and cached <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">LiftOver</span></code> object backed\nby the chain file specified in <em>resources</em>.  When multiple hg38 mappings\nexist for a given position, the one with the highest chain score is returned.</p><p class=\"rubric\">Notes</p><p>pyliftover uses <strong>0-based</strong> coordinates (BED convention).  GWAS summary\nstatistics files typically use <strong>1-based</strong> coordinates (VCF/Ensembl\nconvention).  The caller (<a class=\"reference internal\" href=\"#pycmplot.liftover.liftover_position\" title=\"pycmplot.liftover.liftover_position\"><code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">liftover_position()</span></code></a>) is responsible for any\ncoordinate-system adjustment.</p><p class=\"rubric\">Examples</p></dd>", "a[href=\"#module-pycmplot.liftover\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot.liftover<a class=\"headerlink\" href=\"#module-pycmplot.liftover\" title=\"Link to this heading\">\uf0c1</a></h2><p>Genome coordinate liftover utilities (hg18 \u2192 hg38 and hg19 \u2192 hg38).</p><p>The <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">pyliftover.LiftOver</span></code> objects are initialised <strong>lazily</strong> \u2014 they\nare created on first use and cached in a module-level dictionary, so\nimporting this module never triggers a file-not-found error even if the\nchain files have not been configured yet.</p>", "a[href=\"#resource-configuration\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Resource configuration<a class=\"headerlink\" href=\"#resource-configuration\" title=\"Link to this heading\">\uf0c1</a></h3><p>Chain file paths are resolved through\n<a class=\"reference internal\" href=\"resources.html#pycmplot.resources.ResourceConfig\" title=\"pycmplot.resources.ResourceConfig\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">ResourceConfig</span></code></a>.  By default, bundled chain\nfiles are used (<code class=\"docutils literal notranslate\"><span class=\"pre\">pycmplot/data/hg19ToHg38.over.chain.gz</span></code> and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">pycmplot/data/hg18ToHg38.over.chain.gz</span></code>).  They can be overridden by\nsetting the environment variables:</p>", "a[href=\"resources.html#pycmplot.resources.ResourceConfig\"]": "<dt class=\"sig sig-object py\" id=\"pycmplot.resources.ResourceConfig\">\n<em class=\"property\"><span class=\"pre\">class</span><span class=\"w\"> </span></em><span class=\"sig-prename descclassname\"><span class=\"pre\">pycmplot.resources.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ResourceConfig</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chain_hg19_hg38:</span> <span class=\"pre\">str</span> <span class=\"pre\">|</span> <span class=\"pre\">None</span> <span class=\"pre\">=</span> <span class=\"pre\">&lt;factory&gt;</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chain_hg18_hg38:</span> <span class=\"pre\">str</span> <span class=\"pre\">|</span> <span class=\"pre\">None</span> <span class=\"pre\">=</span> <span class=\"pre\">&lt;factory&gt;</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">geneinfo_hg38:</span> <span class=\"pre\">str</span> <span class=\"pre\">|</span> <span class=\"pre\">None</span> <span class=\"pre\">=</span> <span class=\"pre\">&lt;factory&gt;</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">geneinfo_hg19:</span> <span class=\"pre\">str</span> <span class=\"pre\">|</span> <span class=\"pre\">None</span> <span class=\"pre\">=</span> <span class=\"pre\">&lt;factory&gt;</span></span></em><span class=\"sig-paren\">)</span><a class=\"reference internal\" href=\"../_modules/pycmplot/resources.html#ResourceConfig\"><span class=\"viewcode-link\"><span class=\"pre\">[source]</span></span></a></dt><dd><p>Bases: <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">object</span></code></p><p>Paths to external reference files used by pycmplot.</p><p>Dataclass grouping the on-disk resources required by pycmplot:</p><p>All three attributes default to values resolved from environment\nvariables or the bundled <code class=\"docutils literal notranslate\"><span class=\"pre\">pycmplot/data/</span></code> directory via\n<code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">importlib.resources.files()</span></code>. Override individual attributes to use\ncustom file locations.</p><p class=\"rubric\">Examples</p><p>Use all bundled defaults:</p></dd>", "a[href=\"#pycmplot.liftover.liftover_hg18_to_hg38\"]": "<dt class=\"sig sig-object py\" id=\"pycmplot.liftover.liftover_hg18_to_hg38\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pycmplot.liftover.</span></span><span class=\"sig-name descname\"><span class=\"pre\">liftover_hg18_to_hg38</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chrom</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">str</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">pos</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">int</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">resources</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"resources.html#pycmplot.resources.ResourceConfig\" title=\"pycmplot.resources.ResourceConfig\"><span class=\"pre\">ResourceConfig</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><span class=\"pre\">int</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span></span><a class=\"reference internal\" href=\"../_modules/pycmplot/liftover.html#liftover_hg18_to_hg38\"><span class=\"viewcode-link\"><span class=\"pre\">[source]</span></span></a></dt><dd><p>Convert a single hg18 (NCBI36) position to its hg38 equivalent.</p><p>Uses a lazily loaded and cached <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">LiftOver</span></code> object\nbacked by the hg18\u2192hg38 chain file specified in <em>resources</em>.  When\nmultiple hg38 mappings exist for a given position, the one with the\nhighest chain score is returned.</p></dd>", "a[href=\"#supported-conversions\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Supported conversions<a class=\"headerlink\" href=\"#supported-conversions\" title=\"Link to this heading\">\uf0c1</a></h3><p>pycmplot harmonises input coordinates to GRCh38. Two source assemblies are\nsupported:</p>", "a[href=\"#pycmplot.liftover.liftover_position\"]": "<dt class=\"sig sig-object py\" id=\"pycmplot.liftover.liftover_position\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pycmplot.liftover.</span></span><span class=\"sig-name descname\"><span class=\"pre\">liftover_position</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">df</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">DataFrame</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hg38_chr_limits</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">dict</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">resources</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"resources.html#pycmplot.resources.ResourceConfig\" title=\"pycmplot.resources.ResourceConfig\"><span class=\"pre\">ResourceConfig</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><span class=\"pre\">DataFrame</span></span></span><a class=\"reference internal\" href=\"../_modules/pycmplot/liftover.html#liftover_position\"><span class=\"viewcode-link\"><span class=\"pre\">[source]</span></span></a></dt><dd><p>Liftover all hg18/hg19 rows in <em>df</em> to hg38 coordinates.</p><p>Iterates over every row in <em>df</em> and dispatches to\n<a class=\"reference internal\" href=\"#pycmplot.liftover.liftover_hg19_to_hg38\" title=\"pycmplot.liftover.liftover_hg19_to_hg38\"><code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">liftover_hg19_to_hg38()</span></code></a> for rows whose <code class=\"docutils literal notranslate\"><span class=\"pre\">BUILD</span></code> column equals\n<code class=\"docutils literal notranslate\"><span class=\"pre\">'hg19'</span></code> or to <a class=\"reference internal\" href=\"#pycmplot.liftover.liftover_hg18_to_hg38\" title=\"pycmplot.liftover.liftover_hg18_to_hg38\"><code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">liftover_hg18_to_hg38()</span></code></a> for rows whose <code class=\"docutils literal notranslate\"><span class=\"pre\">BUILD</span></code>\ncolumn equals <code class=\"docutils literal notranslate\"><span class=\"pre\">'hg18'</span></code>.  Rows with any other build value are passed\nthrough unchanged.  Rows for which liftover returns <code class=\"docutils literal notranslate\"><span class=\"pre\">None</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">0</span></code>\n(unmappable positions) are silently dropped.</p><p>Two provenance columns are added to the returned DataFrame so that the\noriginal coordinates remain accessible:</p><p>After processing, the <code class=\"docutils literal notranslate\"><span class=\"pre\">BUILD</span></code> column is updated to <code class=\"docutils literal notranslate\"><span class=\"pre\">'hg38'</span></code> for all\nrows.</p><p class=\"rubric\">Examples</p></dd>", "a[href=\"#pycmplot-liftover\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot.liftover<a class=\"headerlink\" href=\"#pycmplot-liftover\" title=\"Link to this heading\">\uf0c1</a></h1><p>Lazy hg18 \u2192 hg38 and hg19 \u2192 hg38 coordinate conversion powered by\n<a class=\"reference external\" href=\"https://github.com/konstantint/pyliftover\">pyliftover</a>.\nConversion is triggered only when a genome-build column is detected (or\nexplicitly named via <code class=\"docutils literal notranslate\"><span class=\"pre\">--build_column</span></code>), and only for rows annotated as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">hg18</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">hg19</span></code>. All other rows are passed through unchanged.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: true, theme: 'light-border',

            });
        };
    };
    console.log("tippy tips loaded!");
};
